create role anon; create role authenticated; create role service_role;
create schema auth; create schema core; create schema access_control;
create schema private_app; create schema people; create schema audit_log; create schema extensions;
create extension pgcrypto with schema extensions;
create function auth.uid() returns uuid language sql stable as $$select (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid$$;
create function auth.jwt() returns jsonb language sql stable as $$select coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb,'{}')$$;
create table auth.users(id uuid primary key default gen_random_uuid(),email text unique,email_confirmed_at timestamptz,encrypted_password text,raw_app_meta_data jsonb default '{}');
create table core.tenants(id uuid primary key default gen_random_uuid(),slug text unique,name text,status text default 'active',staff_limit int default 3);
create table access_control.subjects(id uuid primary key default gen_random_uuid(),auth_user_id uuid unique not null references auth.users(id),email text,full_name text,status text default 'active',must_change_password boolean default false);
create table access_control.memberships(id uuid primary key default gen_random_uuid(),subject_id uuid references access_control.subjects(id),tenant_id uuid references core.tenants(id),scope text,status text default 'active');
create unique index membership_unique on access_control.memberships(subject_id,tenant_id) where scope='tenant';
create table access_control.roles(id uuid primary key default gen_random_uuid(),tenant_id uuid,scope text,role_key text,name_ar text);
create table access_control.role_permissions(role_id uuid references access_control.roles(id),permission_key text,primary key(role_id,permission_key));
create table access_control.membership_roles(membership_id uuid references access_control.memberships(id),role_id uuid references access_control.roles(id),primary key(membership_id,role_id));
create table people.staff_profiles(id uuid primary key default gen_random_uuid(),tenant_id uuid references core.tenants(id),membership_id uuid unique references access_control.memberships(id),full_name text,email text,role_key text,account_status text default 'profile_only',employment_status text default 'active',metadata jsonb default '{}');
create unique index staff_email_unique on people.staff_profiles(tenant_id,email) where email is not null;
create table access_control.tenant_invitations(id uuid primary key default gen_random_uuid(),tenant_id uuid references core.tenants(id),full_name text,email text,role_key text,token_hash text unique,status text default 'pending',expires_at timestamptz default now()+interval '7 days',accepted_by_subject_id uuid,accepted_at timestamptz);
create table audit_log.events(id uuid primary key default gen_random_uuid(),tenant_id uuid,actor_subject_id uuid,action text,resource_type text,resource_id text,context jsonb,occurred_at timestamptz default now());
create function private_app.current_plan_limit(uuid,text) returns jsonb language sql stable as $$select jsonb_build_object('limitValue',staff_limit,'enforceable',true,'enforcement','hard') from core.tenants where id=$1$$;
create function private_app.tenant_plan_usage_count(uuid,text) returns bigint language sql stable as $$select count(*) from access_control.memberships where tenant_id=$1 and scope='tenant' and status in ('active','invited')$$;
